{
  "@context": "https://schema.org",
  "@type": "WebApplication",
  "name": "Generator Laporan & Investigasi Insiden K3 Online",
  "url": "https://wahanatotalita.com/tools/laporan-insiden/",
  "description": "Aplikasi formulir laporan kecelakaan kerja dan analisis akar penyebab 5-Why serta SCAT model sesuai regulasi Permenaker No. 03/1998.",
  "applicationCategory": "BusinessApplication",
  "operatingSystem": "All",
  "offers": { "@type": "Offer", "price": "0", "priceCurrency": "IDR" }
}

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Berapa batas waktu wajib pelaporan kecelakaan kerja ke Dinas Tenaga Kerja?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Berdasarkan Permenaker No. 03/MEN/1998 Pasal 3, pengurus atau pengusaha wajib melaporkan tiap kecelakaan kerja yang terjadi di tempat kerja kepada Kepala Kantor Departemen Tenaga Kerja setempat dalam waktu tidak lebih dari 2 x 24 jam terhitung sejak terjadinya kecelakaan."
      }
    },
    {
      "@type": "Question",
      "name": "Apa tujuan utama investigasi kecelakaan kerja?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Tujuan utama investigasi kecelakaan K3 bukanlah untuk mencari kesalahan atau menghukum individu (blame culture), melainkan untuk menemukan kelemahan sistem manajemen dan akar penyebab mendasar (root cause) guna merancang tindakan korektif dan pencegahan (CAPA) agar kecelakaan serupa tidak terulang kembali di masa depan."
      }
    },
    {
      "@type": "Question",
      "name": "Bagaimana cara melakukan analisis akar masalah menggunakan metode 5-Why?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Metode 5-Why dilakukan dengan menanyakan pertanyaan 'Mengapa?' secara beruntun minimal 5 kali terhadap suatu peristiwa. Pertanyaan pertama mengidentifikasi penyebab langsung (immediate cause), dan pertanyaan-pertanyaan berikutnya menggali lebih dalam hingga menemukan kegagalan sistemik (manajemen, pelatihan, SOP, atau pemeliharaan) sebagai akar masalah."
      }
    }
  ]
}

inline_styles:
:root {
  --navy-dark: #071524;
  --navy: #0D233A;
  --navy-light: #183654;
  --orange: #E8611A;
  --orange-hover: #cf5213;
  --orange-light: #fff2ea;
  --slate-50: #F8FAFC;
  --slate-100: #F1F5F9;
  --slate-200: #E2E8F0;
  --slate-300: #CBD5E1;
  --slate-600: #475569;
  --slate-700: #334155;
  --slate-900: #0F172A;
  --radius-md: 12px;
  --radius-lg: 16px;
  --shadow-sm: 0 2px 8px rgba(13,35,58,0.06);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: 'Source Sans 3', system-ui, -apple-system, sans-serif;
  background: var(--slate-50);
  color: var(--slate-900);
  line-height: 1.6;
}
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

/* HERO */
.inc-hero {
  background: linear-gradient(135deg, #071524 0%, #0D233A 60%, #183654 100%);
  color: #fff;
  padding: 58px 0 44px;
  position: relative;
  overflow: hidden;
  border-bottom: 3px solid var(--orange);
}
.inc-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
                    linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);
  background-size: 36px 36px;
  pointer-events: none;
}
.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(232, 97, 26, 0.18);
  border: 1px solid rgba(232, 97, 26, 0.4);
  padding: 6px 14px;
  border-radius: 999px;
  color: #FFA573;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 14px;
}
.inc-hero h1 {
  font-family: 'Lexend', sans-serif;
  font-size: clamp(1.8rem, 3.6vw, 2.7rem);
  font-weight: 800;
  line-height: 1.2;
  margin-bottom: 12px;
}
.inc-hero h1 span { color: var(--orange); }
.inc-hero p {
  color: #CBD5E1;
  font-size: 1.05rem;
  max-width: 760px;
  margin-bottom: 20px;
}
.hero-tags { display: flex; flex-wrap: wrap; gap: 8px; }
.hero-tag {
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  padding: 4px 12px;
  border-radius: 6px;
  font-size: 0.82rem;
  color: #E2E8F0;
}

/* WORKSPACE LAYOUT */
.inc-wrapper { padding: 40px 0 60px; }
.card-box {
  background: #fff;
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  padding: 28px;
  margin-bottom: 28px;
}
.card-header-line {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 2px solid var(--slate-100);
  padding-bottom: 16px;
  margin-bottom: 22px;
}
.card-title {
  font-family: 'Lexend', sans-serif;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--navy);
  display: flex;
  align-items: center;
  gap: 10px;
}

/* FORM FIELDS */
.form-grid-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-bottom: 16px;
}
.form-grid-3 {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 16px;
  margin-bottom: 16px;
}
@media (max-width: 768px) {
  .form-grid-2, .form-grid-3 { grid-template-columns: 1fr; }
}
.form-field { margin-bottom: 14px; }
.form-label {
  display: block;
  font-size: 0.84rem;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 6px;
}
.form-input {
  width: 100%;
  padding: 10px 14px;
  border: 1.5px solid var(--slate-200);
  border-radius: var(--radius-md);
  font-size: 0.92rem;
  color: var(--slate-900);
  background: #fff;
}
.form-input:focus { outline: none; border-color: var(--orange); }
textarea.form-input { min-height: 80px; resize: vertical; }

/* 5-WHY CHAIN */
.why-step-box {
  background: var(--slate-50);
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-md);
  padding: 14px 18px;
  margin-bottom: 12px;
  position: relative;
}
.why-label {
  font-size: 0.8rem;
  font-weight: 800;
  color: var(--orange);
  text-transform: uppercase;
  margin-bottom: 4px;
}

/* CAPA TABLE */
.capa-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.88rem;
  margin: 16px 0;
}
.capa-table th {
  background: var(--navy);
  color: #fff;
  padding: 10px 12px;
  text-align: left;
}
.capa-table td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--slate-200);
  vertical-align: top;
}

/* ACTIONS */
.btn-submit-inc {
  background: var(--orange);
  color: #fff;
  border: none;
  padding: 12px 24px;
  border-radius: var(--radius-md);
  font-size: 0.95rem;
  font-weight: 700;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.btn-submit-inc:hover { background: var(--orange-hover); }

/* EDITORIAL ARTICLE */
.editorial-box {
  background: #fff;
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-lg);
  padding: 36px;
  margin-bottom: 32px;
}
.editorial-title {
  font-family: 'Lexend', sans-serif;
  font-size: 1.45rem;
  font-weight: 800;
  color: var(--navy);
  margin-bottom: 16px;
  border-left: 4px solid var(--orange);
  padding-left: 14px;
}
.editorial-p {
  color: var(--slate-700);
  font-size: 0.96rem;
  line-height: 1.7;
  margin-bottom: 16px;
}

/* FAQ */
.faq-item {
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-md);
  margin-bottom: 12px;
  overflow: hidden;
  background: #fff;
}
.faq-q {
  width: 100%;
  padding: 16px 20px;
  text-align: left;
  background: #fff;
  border: none;
  font-family: 'Lexend', sans-serif;
  font-size: 0.98rem;
  font-weight: 700;
  color: var(--navy);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.faq-q:hover { background: var(--slate-50); }
.faq-a {
  padding: 0 20px 18px;
  color: var(--slate-700);
  font-size: 0.92rem;
  line-height: 1.65;
  display: none;
}
.faq-item.active .faq-a { display: block; }
.faq-item.active .faq-icon { transform: rotate(180deg); }
.faq-icon { transition: transform 0.2s; }

